import React, { useMemo } from "react";
import {
  CheckCircle,
  Key,
  Shield,
  Lock,
  UploadCloud
} from "lucide-react";

const NODE_RADIUS = 24;
const LEVEL_GAP = 110;
const SIBLING_GAP = 90;
const HORIZONTAL_GAP = 220;

const CryptoFlow = ({ currentStep = 0, mode = "hybrid" }) => {
  const hybrid = [
    {
      title: "Ephemeral Agreement",
      sub: "X25519",
      icon: Key,
      children: ["Generate key", "Exchange values"],
    },
    {
      title: "Encapsulate",
      sub: "Kyber",
      icon: Shield,
      children: ["Shared secret", "Ciphertext"],
    },
    {
      title: "HKDF",
      sub: "SHA-256",
      icon: Key,
      children: ["Mix salt", "Expand key"],
    },
    {
      title: "AES Encrypt",
      sub: "GCM",
      icon: Lock,
      children: ["Encrypt", "Tag"],
    },
    {
      title: "Upload",
      sub: "MinIO",
      icon: UploadCloud,
      children: ["Pack", "Store"],
    },
  ];

  const phases = hybrid; // rsa similar mapping later

  const color = mode === "hybrid" ? "#00ff9d" : "#a855f7";
  const childText = mode === "hybrid" ? "#00ff9d" : "#d8b4fe";

  const { nodes, edges, width, height } = useMemo(() => {
    const nodes = [];
    const edges = [];

    let x = 120;
    const y = 160;

    phases.forEach((p, i) => {
      nodes.push({ id: `p-${i}`, x, y, phase: i, ...p });

      const branchUp = i % 2 === 1;

      p.children.forEach((c, k) => {
        const offset = (k - (p.children.length - 1) / 2) * SIBLING_GAP;
        const cx = x + offset;
        const cy = branchUp ? y - LEVEL_GAP : y + LEVEL_GAP;

        nodes.push({
          id: `c-${i}-${k}`,
          x: cx,
          y: cy,
          label: c,
          child: true,
          parentPhase: i,
        });

        edges.push({ from: `p-${i}`, to: `c-${i}-${k}` });
      });

      if (i > 0) edges.push({ from: `p-${i - 1}`, to: `p-${i}` });

      x += HORIZONTAL_GAP;
    });

    return { nodes, edges, width: x + 120, height: 340 };
  }, [phases]);

  return (
    <div className="bg-black/40 border border-scifi-border rounded-xl overflow-x-auto">
      <svg width={width} height={height}>

        {/* EDGES */}
        {edges.map((e, i) => {
          const a = nodes.find(n => n.id === e.from);
          const b = nodes.find(n => n.id === e.to);
          const active = currentStep > (a.phase ?? a.parentPhase);

          return (
            <line
              key={i}
              x1={a.x}
              y1={a.y}
              x2={b.x}
              y2={b.y}
              stroke={active ? color : "#2a2a2a"}
              strokeWidth="2"
            />
          );
        })}

        {/* NODES */}
        {nodes.map((n, i) => {
          if (n.child) {
            const done = currentStep > n.parentPhase;

            return (
              <g key={i}>
                <circle
                  cx={n.x}
                  cy={n.y}
                  r={10}
                  fill={done ? color : "#0b0f14"}
                  stroke={done ? color : "#444"}
                  strokeWidth="2"
                />
                <text
                  x={n.x}
                  y={n.y + 22}
                  fontSize="11"
                  textAnchor="middle"
                  fill={childText}
                  fontFamily="monospace"
                >
                  {n.label}
                </text>
              </g>
            );
          }

          const done = currentStep >= n.phase + 1;
          const Icon = n.icon;

          return (
            <g key={i}>
              {done && (
                <circle cx={n.x} cy={n.y} r={NODE_RADIUS + 6} fill={color} opacity="0.1" />
              )}

              <circle
                cx={n.x}
                cy={n.y}
                r={NODE_RADIUS}
                fill="#0b0f14"
                stroke={done ? color : "#444"}
                strokeWidth="2"
              />

              {/* ICON OR CHECK */}
              <foreignObject x={n.x - 10} y={n.y - 10} width={20} height={20}>
                {done ? (
                  <CheckCircle size={18} color={color} />
                ) : (
                  <Icon size={18} color="#666" />
                )}
              </foreignObject>

              {/* TEXT */}
              <text
                x={n.x}
                y={n.y + 42}
                fontSize="12"
                textAnchor="middle"
                fill={done ? "white" : "#777"}
                fontWeight="bold"
              >
                {n.title}
              </text>

              <text
                x={n.x}
                y={n.y + 58}
                fontSize="10"
                textAnchor="middle"
                fill="#666"
                fontFamily="monospace"
              >
                {n.sub}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
};

export default CryptoFlow;
